impl Solution {
    pub fn min_moves(target: i32, max_doubles: i32) -> i32 {
        let mut current = 1;
        let mut doubles_used = 0;
        let mut moves = 0;

        while current < target {
            if doubles_used < max_doubles && current * 2 <= target {
                current *= 2;
                doubles_used += 1;
            } else {
                let diff = target - current;
                moves += diff;
                break;
            }
            moves += 1;
        }

        moves
    }
}

